// Manda o boleto so na vespera e no dia do vencimento.
const DIAS_AVISO = [1, 0];       // 1 = vespera, 0 = no dia
const AVISAR_ATRASADO = true;    // true = avisa todo dia enquanto estiver atrasado

const resp = $input.first().json;
if (!resp.ok) throw new Error('Scraper falhou: ' + resp.erro);

const hoje = $now.setZone('America/Sao_Paulo').startOf('day');
const brl = (v) => v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const saida = [];
for (const b of resp.boletos) {
  if (!b.linhaDigitavel || !b.vencimento) continue;
  const venc = DateTime.fromISO(b.vencimento, { zone: 'America/Sao_Paulo' }).startOf('day');
  const dias = Math.round(venc.diff(hoje, 'days').days);

  let titulo = null;
  if (dias === 0 && DIAS_AVISO.includes(0)) titulo = '🔴 <b>Vence HOJE</b>';
  else if (dias === 1 && DIAS_AVISO.includes(1)) titulo = '⏰ <b>Vence AMANHÃ</b>';
  else if (dias > 1 && DIAS_AVISO.includes(dias)) titulo = '📅 <b>Vence em ' + dias + ' dias</b>';
  else if (dias < 0 && AVISAR_ATRASADO) titulo = '⚠️ <b>EM ATRASO</b> há ' + (-dias) + ' dias';
  if (!titulo) continue;

  const caption = [
    titulo,
    '',
    '<b>' + b.conta + '</b>, parcela ' + b.parcela,
    'Valor: ' + brl(b.valor),
    'Vencimento: ' + venc.toFormat('dd/MM/yyyy'),
    '',
    'Linha digitável (toque pra copiar):',
    '<code>' + b.linhaDigitavel + '</code>',
  ].join('\n');

  const item = { json: { caption, temPdf: !!b.pdfBase64 } };
  if (b.pdfBase64) {
    item.binary = {
      data: {
        data: b.pdfBase64,
        mimeType: 'application/pdf',
        fileName: 'senac-parcela-' + b.parcela.replace('/', '-') + '.pdf',
      },
    };
  }
  saida.push(item);
}

return saida;
